import{_ as o,o as a,c as t,ag as r}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Frameworks e recursos","description":"","frontmatter":{},"headers":[],"relativePath":"pt/bridge/index.md","filePath":"pt/bridge/index.md"}'),s={name:"pt/bridge/index.md"};function d(n,e,c,i,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="frameworks-e-recursos" tabindex="-1">Frameworks e recursos <a class="header-anchor" href="#frameworks-e-recursos" aria-label="Permalink to &quot;Frameworks e recursos&quot;">​</a></h1><p>Cada script Nayretis comunica com o seu servidor através da bridge do <code>nay_lib</code>. Esta deteta o seu framework, inventário, target e notificações da primeira vez que é usada, por isso o mesmo script funciona em todas as stacks suportadas.</p><h2 id="stacks-suportadas" tabindex="-1">Stacks suportadas <a class="header-anchor" href="#stacks-suportadas" aria-label="Permalink to &quot;Stacks suportadas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Módulo</th><th>Adaptadores</th><th>Alternativa</th></tr></thead><tbody><tr><td>Framework</td><td><code>qbox</code> (qbx_core), <code>ox</code> (ox_core), <code>esx</code> (es_extended), <code>qbcore</code> (qb-core), <code>custom</code></td><td>nenhuma, o script para com um erro</td></tr><tr><td>Inventário</td><td><code>ox_inventory</code>, <code>qs-inventory</code>, <code>qb-inventory</code></td><td><code>framework</code> (o inventário do próprio framework)</td></tr><tr><td>Target</td><td><code>ox_target</code>, <code>qb-target</code></td><td><code>none</code> (avisos de tecla)</td></tr><tr><td>Notificações</td><td><code>ox_lib</code>, <code>nayretis</code> (só quando forçado)</td><td><code>framework</code>, depois <code>native</code> (feed do GTA)</td></tr></tbody></table><p>A deteção segue a ordem da tabela. Inicie o <code>nay_lib</code> <strong>depois</strong> dos recursos de framework, inventário e target, caso contrário estes não podem ser detetados.</p><h2 id="forcar-um-adaptador" tabindex="-1">Forçar um adaptador <a class="header-anchor" href="#forcar-um-adaptador" aria-label="Permalink to &quot;Forçar um adaptador&quot;">​</a></h2><p>Se a deteção escolher o recurso errado, force-o no <code>server.cfg</code> com <code>setr</code> (o cliente também lê o valor):</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;esx&quot;</span></span>
<span class="line"><span>setr nay:inventory &quot;ox_inventory&quot;</span></span>
<span class="line"><span>setr nay:target &quot;ox_target&quot;</span></span>
<span class="line"><span>setr nay:notify &quot;native&quot;</span></span></code></pre></div><p>Os valores são os nomes de adaptador acima, ou <code>auto</code> (a predefinição). Consulte <a href="/pt/nay-lib/convars">Convars</a>.</p><p>Usa um framework que não está na lista? Escreva um <a href="/pt/bridge/custom">adaptador personalizado</a>.</p><h2 id="limitacoes-conhecidas" tabindex="-1">Limitações conhecidas <a class="header-anchor" href="#limitacoes-conhecidas" aria-label="Permalink to &quot;Limitações conhecidas&quot;">​</a></h2><ul><li><strong>ox_core</strong>: não existe flag de serviço, por isso o grupo ativo é tratado como a profissão em serviço. O grau mais alto de um grupo conta como chefe.</li><li><strong>ox_inventory</strong> (em qualquer framework): os itens utilizáveis têm de existir em <code>ox_inventory/data/items.lua</code>. O ox_inventory só chama o callback do item para itens sem <code>consume</code>, <code>client.export</code> ou <code>server.export</code>.</li><li><strong>qb-inventory</strong>: os metadados dos itens são ignorados na contagem de itens.</li><li><strong>qs-inventory</strong>: os resultados de adicionar e retirar itens não estão documentados. Qualquer resultado diferente de <code>false</code> é tratado como sucesso.</li><li><strong>ESX</strong>: as notificações usam o <code>esx_notify</code> quando está iniciado, e o feed do GTA caso contrário.</li></ul>`,12)])])}const h=o(s,[["render",d]]);export{m as __pageData,h as default};
